import { Button, toast } from "march/ui"
import { star } from "march/icons"

// başarımlar: her basışta mor yıldızlı, kapat düğmesiz, belirerek gelen bir bildirim
const badges = ["İlk adım", "Hızlı koşucu", "Gece kuşu", "Takım oyuncusu"]

export function Achievements() {
  let $i = 0
  return <Button variant="primary" on:click={() => { toast(`Başarım: ${badges[$i % badges.length]}`, { icon: star, color: "brand-purple", closable: false, motion: "fade" }); $i++ }}>
    Başarım kazan ({$i})
  </Button>
}

import { Button, toast } from "march/ui"

// e-postayı arşivle: bildirimde "Geri al"; geri alınınca ileti listeye döner
export function ArchiveUndo() {
  let $mails = ["Toplantı notları", "Fatura", "Bülten"]
  const archive = (m: string) => {
    $mails = $mails.filter((x) => x !== m)
    toast(`"${m}" arşivlendi`, { kind: "success", action: { label: "Geri al", run: () => { $mails = [...$mails, m] } } })
  }
  return <ul>{$mails.map((m) => <li>{m} <Button size="sm" variant="ghost" on:click={() => archive(m)}>Arşivle</Button></li>)}</ul>
}

import { test, expect, renderTest } from "march/testing"
import { ToastLab } from "./ToastLab.tsx"

// ToastLab'in testleri: kaydedince Testler sekmesinde çalışır
test("toast() bir bildirim ekler, clear() hepsini kaldırır", async () => {
  const s = renderTest(() => <ToastLab />)
  await s.click("Hepsini temizle")
  await s.click("Bilgi")
  await s.click("Başarı")
  expect(s.get(".lab-count")?.textContent).toBe("2 bildirim")
  await s.click("Hepsini temizle")
  expect(s.get(".lab-count")?.textContent).toBe("0 bildirim")
})

test("ToastHost bildirimi metniyle çizer", async () => {
  const s = renderTest(() => <ToastLab />)
  await s.click("Hepsini temizle")
  await s.click("Uyarı")
  expect(s.get(".lab-host")?.textContent).toContain("Dikkat")
})
